import nodemailer, { type SendMailOptions } from 'nodemailer';

const smtpUser = (process.env.SMTP_USER || '').trim();
// Hostinger rejects forged or ambiguously formatted From addresses. Use the
// authenticated mailbox itself, while allowing a professional display name
// configured in SMTP_FROM when its address belongs to that mailbox.
const configuredFrom = (process.env.SMTP_FROM || '').trim();
const configuredFromAddress = configuredFrom.match(/<([^>]+)>/)?.[1]?.trim() || configuredFrom;
const safeFrom = smtpUser && configuredFromAddress.toLowerCase() === smtpUser.toLowerCase()
  ? configuredFrom
  : smtpUser
    ? `OB Brokers Team <${smtpUser}>`
    : 'OB Brokers Team <no-reply@osvaldobello.com>';

export const SMTP_CONFIG = {
  host: process.env.SMTP_HOST || 'smtp.hostinger.com',
  port: Number(process.env.SMTP_PORT) || 465,
  secure: (Number(process.env.SMTP_PORT) || 465) === 465,
  auth: {
    user: process.env.SMTP_USER || '',
    pass: process.env.SMTP_PASS || '',
  },
  from: safeFrom,
};

const transport = nodemailer.createTransport(SMTP_CONFIG);

function assertSmtpConfigured() {
  if (!SMTP_CONFIG.auth.user || !SMTP_CONFIG.auth.pass) {
    throw new Error('El correo transaccional no está configurado. Completa SMTP_USER y SMTP_PASS en Production.');
  }
}

// Every application email goes through this single Hostinger transport. Auth
// links are generated by Supabase but delivered from here as well.
export const mailer = {
  sendMail: async (options: SendMailOptions) => {
    assertSmtpConfigured();
    return transport.sendMail(options);
  },
};
const PUBLIC_ASSETS_URL = `${
  process.env.NEXT_PUBLIC_SUPABASE_URL || 'https://whrimmszdeghblbktivp.supabase.co'
}/storage/v1/object/public/public-assets`;
const WHITE_LOGO_URL = `${PUBLIC_ASSETS_URL}/ob-brokers-team/brand/logo-horizontal-white-v2.png`;
