export async function sendOperationalNotificationEmail({ recipients, subject, title, message, actionUrl, actionLabel = 'Abrir en el CRM' }: SendOperationalNotificationEmailOptions) {
  const to = [...new Set(recipients.map((email) => email.trim().toLowerCase()).filter((email) => /^\S+@\S+\.\S+$/.test(email)))];
  if (!to.length) return;
  const action = actionUrl ? `<p style="margin:24px 0 0"><a href="${escapeHtml(actionUrl)}" style="display:inline-block;background:${EMAIL_HEADER_COLOR};color:#fff;padding:12px 18px;border-radius:9px;text-decoration:none;font-weight:700">${escapeHtml(actionLabel)}</a></p>` : '';
  const html = `<!doctype html><html lang="es"><body style="margin:0;background:#f8fafc;font-family:Arial,sans-serif;color:#0f172a"><main style="max-width:620px;margin:32px auto;background:#fff;border:1px solid #e2e8f0;border-radius:18px;overflow:hidden"><header style="padding:28px 32px;background:${EMAIL_HEADER_COLOR};color:#fff"><h1 style="margin:0;font-size:23px">${escapeHtml(title)}</h1></header><section style="padding:28px 32px;font-size:14px;line-height:1.6"><p style="margin:0">${escapeHtml(message)}</p>${action}</section></main></body></html>`;
  await mailer.sendMail({ from: SMTP_CONFIG.from, to, subject, html });
}

export async function sendProjectInquiryEmail(options: SendProjectInquiryEmailOptions) {
  const customerEmail = options.to.trim().toLowerCase();
  if (!/^\S+@\S+\.\S+$/.test(customerEmail)) throw new Error('El correo del solicitante no es válido.');

  const responsibleRecipients = [...new Set(
    options.responsibleRecipients
      .map((email) => email.trim().toLowerCase())
      .filter((email) => /^\S+@\S+\.\S+$/.test(email) && email !== customerEmail)
  )];
  const isVisit = options.requestType === 'site_visit';
  const title = isVisit ? 'Solicitud de visita al proyecto' : 'Solicitud de información';
  const safe = {
    fullName: escapeHtml(options.fullName),
    phone: escapeHtml(options.phone),
    email: escapeHtml(options.email),
    profile: escapeHtml(options.profileLabel),
    agency: escapeHtml(options.agencyName || 'No aplica'),
    project: escapeHtml(options.projectName),
    typology: escapeHtml(options.typology || 'Sin especificar'),
    message: escapeHtml(options.message || 'Sin mensaje adicional').replace(/\n/g, '<br>'),
    reference: escapeHtml(options.reference),
    projectUrl: escapeHtml(options.projectUrl),
  };

  const html = `<!doctype html><html lang="es"><body style="margin:0;background:#f8fafc;font-family:Arial,sans-serif;color:#0f172a"><main style="max-width:620px;margin:32px auto;background:#fff;border:1px solid #e2e8f0;border-radius:20px;overflow:hidden"><header style="padding:30px 34px;background:${EMAIL_HEADER_COLOR};color:#fff"><p style="margin:0 0 8px;font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:#cbd5e1">${safe.reference}</p><h1 style="margin:0;font-size:24px">${title}</h1></header><section style="padding:30px 34px;font-size:14px;line-height:1.65"><p style="margin:0 0 22px">Hola, <strong>${safe.fullName}</strong>. Recibimos tu solicitud sobre <strong>${safe.project}</strong>. El equipo responsable del master broker tiene una copia de este correo y dará seguimiento directamente.</p><table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #e2e8f0;border-radius:14px;padding:14px 18px;background:#f8fafc"><tr><td style="padding:6px 0;color:#64748b;font-size:12px">Proyecto</td><td align="right" style="padding:6px 0;font-size:12px;font-weight:800">${safe.project}</td></tr><tr><td style="padding:6px 0;color:#64748b;font-size:12px">Solicitud</td><td align="right" style="padding:6px 0;font-size:12px;font-weight:800">${title}</td></tr><tr><td style="padding:6px 0;color:#64748b;font-size:12px">Perfil</td><td align="right" style="padding:6px 0;font-size:12px;font-weight:800">${safe.profile}</td></tr><tr><td style="padding:6px 0;color:#64748b;font-size:12px">Agencia</td><td align="right" style="padding:6px 0;font-size:12px;font-weight:800">${safe.agency}</td></tr><tr><td style="padding:6px 0;color:#64748b;font-size:12px">Teléfono</td><td align="right" style="padding:6px 0;font-size:12px;font-weight:800">${safe.phone}</td></tr><tr><td style="padding:6px 0;color:#64748b;font-size:12px">Correo</td><td align="right" style="padding:6px 0;font-size:12px;font-weight:800">${safe.email}</td></tr><tr><td style="padding:6px 0;color:#64748b;font-size:12px">Modelo</td><td align="right" style="padding:6px 0;font-size:12px;font-weight:800">${safe.typology}</td></tr></table><div style="margin:20px 0 0;padding:16px 18px;border-left:4px solid #7c3aed;background:#faf5ff"><p style="margin:0 0 6px;color:#64748b;font-size:11px;text-transform:uppercase;letter-spacing:.12em">Mensaje</p><p style="margin:0">${safe.message}</p></div><p style="margin:24px 0 0;text-align:center"><a href="${safe.projectUrl}" style="display:inline-block;background:${EMAIL_HEADER_COLOR};color:#fff;padding:12px 20px;border-radius:999px;text-decoration:none;font-weight:700">Ver proyecto</a></p><p style="margin:22px 0 0;color:#64748b;font-size:12px">Puedes responder este correo para continuar la conversación con el responsable comercial.</p></section><footer style="padding:20px 34px;background:#f8fafc;border-top:1px solid #e2e8f0;color:#94a3b8;font-size:11px;text-align:center">OB Brokers Team · Solicitud vinculada al proyecto ${safe.project}</footer></main></body></html>`;

  await mailer.sendMail({
    from: SMTP_CONFIG.from,
    to: customerEmail,
    ...(responsibleRecipients.length ? { cc: responsibleRecipients, replyTo: responsibleRecipients[0] } : {}),
    subject: `${title} · ${options.projectName} · ${options.reference}`,
    html,
  });
}

export async function sendSignedAgreementEmail({ recipients, agreementTitle, brokerName, expiresAt, pdf }: { recipients: string[]; agreementTitle: string; brokerName: string; expiresAt: Date; pdf: Uint8Array }) {
  const to = [...new Set(recipients.map((email) => email.trim().toLowerCase()).filter((email) => /^\S+@\S+\.\S+$/.test(email)))];
  if (!to.length) return;
  const safeTitle = escapeHtml(agreementTitle); const safeBroker = escapeHtml(brokerName); const expiry = escapeHtml(expiresAt.toLocaleDateString('es-DO', { day: 'numeric', month: 'long', year: 'numeric' }));
  await mailer.sendMail({ from: SMTP_CONFIG.from, to, subject: `Acuerdo firmado y sellado · ${agreementTitle}`, html: `<!doctype html><html lang="es"><body style="font-family:Arial,sans-serif;color:#0f172a"><main style="max-width:620px;margin:auto;border:1px solid #e2e8f0;border-radius:16px;overflow:hidden"><header style="background:${EMAIL_HEADER_COLOR};padding:28px;color:#fff"><h1 style="margin:0;font-size:22px">Acuerdo firmado y sellado</h1></header><section style="padding:28px"><p>El acuerdo <strong>${safeTitle}</strong> fue firmado por <strong>${safeBroker}</strong>.</p><p>Vigencia hasta: <strong>${expiry}</strong>.</p><p>Se adjunta el PDF final con evidencia de firma y sello. Consérvalo en el expediente comercial.</p></section></main></body></html>`, attachments: [{ filename: 'acuerdo-firmado.pdf', content: Buffer.from(pdf), contentType: 'application/pdf' }] });
}

function escapeHtml(value: string) {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

